function base45Encode(data, alphabet = REVERSED_B45) {
  const leadingZeros = leadingZeroBytes(data);
  let result = '::'.repeat(leadingZeros);

  let num = 0n;
  for (let i = leadingZeros; i < data.length; i++) {
    num = (num << 8n) | BigInt(data[i]);
  }

  if (num === 0n) {
    return result;
  }

  let base45Str = '';
  while (num > 0n) {
    base45Str = alphabet[Number(num % 45n)] + base45Str;
    num = num / 45n;
  }

  return result + base45Str;
}

