function createEventEmitter() {
  const listeners = new Map();

  function subscribe(event, handler, options = {}) {
    if (!listeners.has(event)) {
      listeners.set(event, []);
    }
    listeners.get(event).push({
      handler,
      priority: options.priority !== undefined ? options.priority : 0,
      once: options.once || false
    });
  }

  function emit(event, ...args) {
    const handlers = listeners.get(event) || [];
    // Sort by priority descending
    const sorted = [...handlers].sort((a, b) => b.priority - a.priority);
    const results = [];
    for (const item of sorted) {
      results.push(item.handler(...args));
      if (item.once) {
        // Remove from original array
        const idx = handlers.indexOf(item);
        if (idx !== -1) handlers.splice(idx, 1);
      }
    }
    return results;
  }

  return { subscribe, emit };
}

