function checksumHex(data, groupSize = 4, sep = '-') {
  const buf = Buffer.from(data);
  if (buf.length === 0) return '';
  let checksum = 0;
  const bytes = Array.from(buf).map(b => { checksum ^= b; return toHexByte(b); });
  bytes.push(toHexByte(checksum));
  const groups = [];
  for (let i = 0; i < bytes.length; i += groupSize) groups.push(bytes.slice(i, i + groupSize).join(''));
  return groups.join(sep);
}

