// - Cache key is JSON of ALL arguments (not just the first)
// - Object arguments have their keys sorted recursively for deterministic keys
// - Cache has a max size; when full, evicts the OLDEST entry (FIFO, not LRU)

function sortKeys(val) {
    if (val === null || typeof val !== 'object') return val;
    if (Array.isArray(val)) return val.map(sortKeys);
    const sorted = {};
    for (const k of Object.keys(val).sort()) sorted[k] = sortKeys(val[k]);
    return sorted;
}

